import{_ as t,a as o,a3 as a,o as s}from"./chunks/framework.yJBLK5ap.js";const g=JSON.parse('{"title":"Automated gold tagging – design","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/AutomatedGoldTagging.md","filePath":"devdoc/AutomatedGoldTagging.md","lastUpdated":1795797312000}'),r={name:"devdoc/AutomatedGoldTagging.md"};function i(n,e,d,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="automated-gold-tagging-–-design" tabindex="-1">Automated gold tagging – design <a class="header-anchor" href="#automated-gold-tagging-–-design" aria-label="Permalink to &quot;Automated gold tagging – design&quot;">​</a></h1><p>Status: implemented. The scripts are described in <a href="./../tools/tagging/README.html">tools/tagging/README.md</a>.</p><h2 id="_0-decisions" tabindex="-1">0. Decisions <a class="header-anchor" href="#_0-decisions" aria-label="Permalink to &quot;0. Decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Decision</th></tr></thead><tbody><tr><td>Approval</td><td>None. Tag automatically when a change is detected.</td></tr><tr><td>RC step</td><td>Skipped. A gorc-style split is tagged gold (<code>A.B.N-1</code>) directly.</td></tr><tr><td>Manual fallback</td><td><code>gorc.sh</code> and <code>gogold.sh</code> stay.</td></tr><tr><td>Notifications</td><td>Existing build notifications on success. Tagging failures go to <code>CICD_WEBHOOK_URL</code>.</td></tr><tr><td>Verifying tagged builds</td><td>Out of scope.</td></tr><tr><td>hpcc4j</td><td>Is tagged, but a change in hpcc4j alone does not trigger a release.</td></tr><tr><td>Upmerge failure</td><td>Automatic tagging is skipped for the whole run.</td></tr><tr><td>Repository missing a tagged branch</td><td>Abort: internal error.</td></tr><tr><td>Cadence</td><td>Nightly, whenever something changed.</td></tr><tr><td>Outstanding RC branches (e.g. 10.4.62-rc1)</td><td>Resolved manually. Ignored by automation.</td></tr><tr><td>Order</td><td>Manifest <code>repositories</code> order. Branches in <code>tagging.branches</code> order. No submodules.</td></tr><tr><td>Tag signing</td><td>Unsigned annotated tags are fine.</td></tr><tr><td>Failure</td><td>Prepare everything locally, then push. On the first push failure, stop all further pushes, notify, and wait for a rerun. The rerun must resume correctly.</td></tr></tbody></table><h2 id="_1-how-the-current-process-works" tabindex="-1">1. How the current process works <a class="header-anchor" href="#_1-how-the-current-process-works" aria-label="Permalink to &quot;1. How the current process works&quot;">​</a></h2><p>The repositories are <code>eclide</code>, <code>HPCC-JAPIs</code> (hpcc4j), <code>ln</code> and <code>hpcc</code>, set in <code>$all</code> in <code>env.sh.example</code>. <code>helm-chart</code> is updated as a side effect of tagging <code>hpcc</code>.</p><h3 id="gorc-sh-a-b-x" tabindex="-1"><code>gorc.sh A.B.x</code> <a class="header-anchor" href="#gorc-sh-a-b-x" aria-label="Permalink to &quot;`gorc.sh A.B.x`&quot;">​</a></h3><p>This wrapper runs <code>cmake_modules/go_rc.sh</code> in each repository on <code>candidate-A.B.x</code>. It waits for a key press.</p><p><code>go_rc.sh</code> on a <code>closedown</code> branch with odd point P:</p><ol><li>Creates <code>candidate-A.B.(P+1)</code> from the <code>.x</code> HEAD. This is the split.</li><li>On <code>.x</code>, bumps the version files to <code>closedown</code>, point P+2: <code>version.cmake</code>, <code>pom.xml</code>, <code>Chart.yaml</code>, and the <code>helmVersion</code> in <code>_helpers.tpl</code>. It commits this as <code>Split off A.B.(P+1)</code> and pushes.</li><li>On the new branch, sets <code>rc</code>, point P+1, sequence 1. It commits, pushes, and creates a tag for each entry in <code>HPCC_PROJECT</code>, e.g. <code>community_A.B.(P+1)-rc1</code>.</li><li>In the platform repository only, it packages the hpcc chart into <code>../helm-chart/docs</code>, re-indexes, and pushes <code>helm-chart</code> master.</li></ol><h3 id="gogold-sh-a-b-p" tabindex="-1"><code>gogold.sh A.B.P</code> <a class="header-anchor" href="#gogold-sh-a-b-p" aria-label="Permalink to &quot;`gogold.sh A.B.P`&quot;">​</a></h3><p><code>go_gold.sh</code> requires <code>rc</code> maturity, an even point, and HEAD equal to the rc tag. It sets <code>release</code>, sequence 1, commits, and tags <code>&lt;project&gt;_A.B.P-1</code>. It publishes the hpcc chart plus the <code>examples/*</code> and <code>managed/*</code> charts.</p><h3 id="other-relevant-pieces" tabindex="-1">Other relevant pieces <a class="header-anchor" href="#other-relevant-pieces" aria-label="Permalink to &quot;Other relevant pieces&quot;">​</a></h3><ul><li><code>update_version_file</code> also writes <code>HPCC_TAG_TIMESTAMP</code>. Preparing the same release twice therefore produces different commit SHAs, which matters for resuming (section 6).</li><li>hpcc4j uses <code>parse_hpcc_pom.sh</code>, which reads <code>&lt;version&gt;</code> in the form <code>A.B.P-SEQ-maturity</code> from <code>pom.xml</code>. The same <code>go_*.sh</code> logic applies.</li><li><code>branch-operations.yml</code> is a reusable workflow that runs upmerge, then sync, under a shared concurrency group. When the job fails, its <code>notify-failure</code> job already posts to <code>CICD_WEBHOOK_URL</code>.</li><li><code>sync-oss-branches.sh</code> already syncs new <code>candidate-*</code> branches and any tag at a branch tip, in manifest order. <strong>Sync needs no change.</strong></li><li><code>build-assets.yml</code> is triggered by the platform <code>community_*</code> tag. It checks out LN and ECLIDE at refs derived from that tag (<code>eclide_…</code>, <code>internal_…</code>). So the <strong>platform tag must be pushed last</strong>, after ln and eclide. The current manifest order (eclide, hpcc4j, helm-chart, ln, platform) already does this.</li></ul><h2 id="_2-target-behaviour" tabindex="-1">2. Target behaviour <a class="header-anchor" href="#_2-target-behaviour" aria-label="Permalink to &quot;2. Target behaviour&quot;">​</a></h2><p>For each branch in <code>tagging.branches</code>, in order (e.g. 10.2.x → 10.8.x):</p><ol><li><strong>Check the release state</strong> of every tagged repository (section 6). If a release is part-done, finish it before doing anything else.</li><li><strong>Detect changes</strong> in each trigger repository since its last split (section 3).</li><li><strong>Decide.</strong> If any trigger repository changed, or the run was forced, release the next point in <strong>every</strong> tagged repository. For example, an <code>eclide</code> fix on 10.4.x releases 10.4.(P+1) in eclide, hpcc4j, ln and platform.</li><li><strong>Prepare</strong> all repositories locally. Nothing is pushed in this step.</li><li><strong>Push</strong> (section 5).</li></ol><p>Upmerge runs first, so a 10.2.x fix also releases 10.4, 10.6 and 10.8. <code>master</code> is never tagged automatically.</p><h2 id="_3-change-detection" tabindex="-1">3. Change detection <a class="header-anchor" href="#_3-change-detection" aria-label="Permalink to &quot;3. Change detection&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P     = point on origin/candidate-A.B.x                     (must be odd, closedown)</span></span>\n<span class="line"><span>last  = origin/candidate-A.B.(P-1)                           (previous split; must exist)</span></span>\n<span class="line"><span>base  = git merge-base origin/candidate-A.B.x last</span></span>\n<span class="line"><span>split = first first-parent commit in base..origin/candidate-A.B.x</span></span>\n<span class="line"><span>        (must be &quot;Split off A.B.(P-1)&quot;)</span></span>\n<span class="line"><span>changed = ! git diff --quiet split origin/candidate-A.B.x</span></span></code></pre></div><p>This compares file contents (trees) rather than counting commits. Upmerges that bring in nothing are common and leave the tree unchanged. This was verified on 10.4.x, where the split was followed by such an upmerge.</p><p>If <code>last</code> is missing or the commit after the base is not a split commit, abort with an internal error. A forced dispatch doesn&#39;t override this, because the version can&#39;t be trusted.</p><h2 id="_4-manifest-changes-branch-policy-json" tabindex="-1">4. Manifest changes (<code>branch-policy.json</code>) <a class="header-anchor" href="#_4-manifest-changes-branch-policy-json" aria-label="Permalink to &quot;4. Manifest changes (`branch-policy.json`)&quot;">​</a></h2><p>Add these per-repository flags:</p><table tabindex="0"><thead><tr><th>id (manifest order)</th><th><code>tag_enabled</code></th><th><code>tag_triggers</code></th></tr></thead><tbody><tr><td>eclide</td><td>true</td><td>true</td></tr><tr><td>hpcc4j</td><td>true</td><td>false</td></tr><tr><td>helm-chart</td><td>false (published with platform)</td><td>false</td></tr><tr><td>ln</td><td>true</td><td>true</td></tr><tr><td>platform</td><td>true</td><td>true</td></tr></tbody></table><p>Also add a top-level section:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tagging&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;branches&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candidate-10.2.x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candidate-10.4.x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candidate-10.6.x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candidate-10.8.x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;helm_chart_repository&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;helm-chart&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>helm_chart_repository</code> names the repository entry that receives the packaged charts.</p><ul><li><code>paused: true</code> blocks tagging in <code>apply</code> mode.</li><li><code>schema_version</code> stays 1, because the new fields are optional for the existing validators.</li><li>Validation: <ul><li>Every <code>tag_enabled</code> repository must have every branch in <code>tagging.branches</code>.</li><li>The platform must be the last <code>tag_enabled</code> repository, because the build trigger depends on it (section 1).</li></ul></li></ul><h2 id="_5-prepare-then-push" tabindex="-1">5. Prepare, then push <a class="header-anchor" href="#_5-prepare-then-push" aria-label="Permalink to &quot;5. Prepare, then push&quot;">​</a></h2><h3 id="prepare-local-only-all-branches-all-repositories" tabindex="-1">Prepare (local only, all branches, all repositories) <a class="header-anchor" href="#prepare-local-only-all-branches-all-repositories" aria-label="Permalink to &quot;Prepare (local only, all branches, all repositories)&quot;">​</a></h3><p>For each branch, then for each tagged repository in manifest order, run <code>go_rc.sh --gold --no-push</code>. The <code>--no-push</code> option records the refs to push instead of pushing them:</p><ul><li><code>.x</code> gets the commit <code>Split off A.B.(P+1)</code>, bumping it to P+2 <code>closedown</code>.</li><li><code>candidate-A.B.(P+1)</code> gets the release commit (<code>release</code>, sequence 1).</li><li>Tags are created for each <code>HPCC_PROJECT</code> entry, e.g. <code>community_A.B.(P+1)-1</code>.</li></ul><p>For the platform, the charts are packaged into the local <code>helm-chart</code> clone in the same step. All branches stack their commits on one local <code>helm-chart</code> master.</p><p>Then check the plan <strong>before any push</strong>:</p><ul><li>Every new tag points at the tip of its new branch.</li><li>The new branch&#39;s parent is the <code>.x</code> commit that was fetched.</li><li>The <code>.x</code> parent is the fetched tip.</li><li>All repositories produced the same version.</li><li><code>git push --dry-run --atomic</code> succeeds for each repository.</li></ul><h3 id="push-strict-order-stop-on-the-first-failure" tabindex="-1">Push (strict order, stop on the first failure) <a class="header-anchor" href="#push-strict-order-stop-on-the-first-failure" aria-label="Permalink to &quot;Push (strict order, stop on the first failure)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for branch in tagging.branches:</span></span>\n<span class="line"><span>  for repo in manifest order (tag_enabled):</span></span>\n<span class="line"><span>    git push --atomic origin \\</span></span>\n<span class="line"><span>      &lt;new .x sha&gt;:refs/heads/candidate-A.B.x \\</span></span>\n<span class="line"><span>      &lt;release sha&gt;:refs/heads/candidate-A.B.(P+1) \\</span></span>\n<span class="line"><span>      refs/tags/&lt;each tag&gt;</span></span>\n<span class="line"><span>  (after all branches) git push origin helm-chart master</span></span></code></pre></div><ul><li><code>--atomic</code> means each repository is either fully released or untouched. The <code>.x</code> update is a fast-forward check against the fetched tip. If someone merged a PR in the meantime, the push is rejected rather than losing that work. Creating the branch or tag fails if it already exists.</li><li>On the first failure: <ul><li>Stop all further pushes, including later repositories, later branches and <code>helm-chart</code>.</li><li>Write the state (which repositories are released and which are pending) to the step summary.</li><li>Fail the job, so the existing <code>notify-failure</code> job posts to <code>CICD_WEBHOOK_URL</code>. Extend that message with the branch, repository and git error.</li></ul></li><li>If tagging fails, <strong>skip sync for this run.</strong> Otherwise OSS gets a part-done release and the build-trigger order is broken. The nightly run, or a rerun, syncs after it completes.</li></ul><h2 id="_6-resuming-after-a-failure-per-repository-release-state" tabindex="-1">6. Resuming after a failure: per-repository release state <a class="header-anchor" href="#_6-resuming-after-a-failure-per-repository-release-state" aria-label="Permalink to &quot;6. Resuming after a failure: per-repository release state&quot;">​</a></h2><p>With per-repository atomic pushes, each tagged repository on a branch is in one of these states:</p><table tabindex="0"><thead><tr><th>State</th><th><code>.x</code></th><th><code>candidate-A.B.(P+1)</code></th><th>Tags</th></tr></thead><tbody><tr><td><strong>pending</strong></td><td>point P, <code>closedown</code>, no split commit for P+1</td><td>absent</td><td>absent</td></tr><tr><td><strong>released</strong></td><td>point P+2; first-parent history contains <code>Split off A.B.(P+1)</code></td><td>exists; at its tip <code>release</code> P+1 sequence 1</td><td>every project tag <code>…A.B.(P+1)-1</code> at the tip of the new branch</td></tr><tr><td>anything else</td><td></td><td></td><td>→ <strong>inconsistent</strong>: internal error, abort, manual repair</td></tr></tbody></table><p>For each branch, take the state of all tagged repositories:</p><ul><li><p><strong>All pending:</strong> normal detection (section 3).</p></li><li><p><strong>All released:</strong> nothing to resume. Run normal detection from the new baseline.</p></li><li><p><strong>Mixed:</strong> this is a part-done release. Its target is P+1, where P is the point of the pending repositories. All of these must hold, or the run aborts:</p><ul><li>Every released repository is at exactly P+1, with <code>.x</code> at P+2.</li><li>Every pending repository is at P.</li><li>The released repositories form a <strong>prefix</strong> of the manifest order. A gap means something other than this process pushed.</li></ul><p>Then prepare and push only the pending repositories. <strong>Change detection is not run</strong>: they must be completed even if nothing in them changed.</p></li><li><p><strong>helm-chart:</strong> for every platform repository in the released state, check that <code>hpcc-A.B.(P+1).tgz</code> is in <code>helm-chart/docs</code>. If not, republish it from the <code>candidate-A.B.(P+1)</code> branch with <code>cmake_modules/publish_helm.sh</code>. This covers a failure after the platform push.</p></li></ul><p>A rerun is the GitHub &quot;Re-run failed jobs&quot; button, or simply the next nightly run. Both work, because the state comes only from the remote repositories, not from the earlier run.</p><h2 id="_7-potential-problems-especially-versions" tabindex="-1">7. Potential problems, especially versions <a class="header-anchor" href="#_7-potential-problems-especially-versions" aria-label="Permalink to &quot;7. Potential problems, especially versions&quot;">​</a></h2><ol><li><p><strong>New SHAs on every prepare.</strong> <code>HPCC_TAG_TIMESTAMP</code> and commit times change, so pending repositories are rebuilt from scratch on a rerun. This is fine because nothing of theirs was pushed. <strong>Never</strong> re-prepare a released repository: existing tags must not be moved. Sync also refuses to overwrite tags that differ.</p></li><li><p><strong>Commits landing between the failure and the rerun.</strong> These are included in the resumed release of the pending repositories, but not in the repositories already released. Each repository&#39;s release is still a consistent snapshot of that repository. This is acceptable because the repositories are released independently today too, but the release is not a snapshot from one moment in time.</p></li><li><p><strong>Nightly upmerge running against a part-done release.</strong> In a released repository, <code>.x</code> is now at P+2 and gets upmerged into higher branches. The normalizer keeps the target&#39;s version, so this is safe. Upmerge never touches point branches.</p></li><li><p><strong>A higher branch released after a lower branch failed.</strong> The push order prevents this within one run. Across runs, the lower branch is resumed first because branches are processed in order. Still, nightly upmerge can carry the lower branch&#39;s changes upward first. Agreed policy: the run stops at the first failure.</p></li><li><p><strong>Repositories disagreeing on the version.</strong> This happens if someone ran <code>gorc</code> or <code>gogold</code> for only some repositories, or after a manual repair. It shows up as inconsistent or as a gap in the prefix, and the run aborts. It is never guessed. The manual fallback <code>gorc.sh --gold</code> should therefore use the same prepare-then-atomic-push path, so it can&#39;t leave states the automation can&#39;t classify. Document: <strong>set <code>paused</code> before running anything manually.</strong></p></li><li><p><strong>Point parity and old RC branches.</strong> <code>.x</code> must be odd and <code>closedown</code>. Old RC branches (e.g. 10.4.62 at rc1) are ignored. Detection uses <code>candidate-A.B.(P-1)</code>, whether it is at rc or release, as the baseline, so an un-golded 10.4.62 doesn&#39;t block 10.4.64.</p><ul><li>However, if someone manually golds 10.4.62 later, <code>gogold.sh</code> pushes a commit to <code>candidate-10.4.62</code>. The merge base with <code>.x</code> is unchanged, so detection is unaffected.</li><li>If an RC point branch is created manually with <code>gorc.sh</code> (not <code>--gold</code>) while automation is active, the next automatic release still works. It just skips one point.</li></ul></li><li><p><strong>The manifest doesn&#39;t match the repositories.</strong> Examples: a new <code>.x</code> branch is added to <code>tagging.branches</code> before its first split exists, or a repository lacks the branch. Both abort with an internal error, as agreed. After <code>gominor.sh</code>, add the new branch only after its first split.</p></li><li><p><strong>Several tags per repository.</strong> <code>HPCC_PROJECT</code> may list more than one project, and <code>do_tag</code> loops over them. The state check and the atomic push must include <strong>all</strong> of them, otherwise a repository could be classified as released while one tag is missing.</p></li><li><p><strong>Partial <code>helm-chart</code> failure.</strong> <code>helm package --dependency-update</code> for the examples needs external chart repositories. If that fails <strong>during prepare</strong>, nothing is pushed. A <code>helm-chart</code> <strong>push</strong> failure happens after the platform tag is pushed: the release is out but the chart isn&#39;t. The resume check in section 6 republishes it. <code>helm repo index</code> rewrites <code>index.yaml</code>, so a concurrent push to <code>helm-chart</code> master causes a non-fast-forward failure, which is fixed by rerunning.</p></li><li><p><strong>OSS sync order.</strong> Sync also pushes in manifest order, so the platform tag reaches OSS after ln and eclide. If sync fails partway, the platform tag may be pushed without an ln tag, or not at all. This problem exists today and is not made worse.</p></li><li><p><strong>Concurrency.</strong> The tagging step runs inside the shared <code>branch-operations</code> concurrency group, after upmerge, and fetches fresh refs after upmerge rather than reusing upmerge&#39;s temporary clones. A human pushing directly is caught by the atomic fast-forward check.</p></li><li><p><strong><code>eval</code> in <code>doit</code>.</strong> Only validated policy and input values (version numbers, <code>candidate-</code> names) may reach <code>go_*.sh</code>.</p></li><li><p><strong>Rerun with old code.</strong> &quot;Re-run failed jobs&quot; reuses the workflow commit from the original run. If the failure was a script bug, the fix needs a new run, i.e. the next nightly run or a new dispatch, not a rerun.</p></li></ol><h2 id="_8-changes-required" tabindex="-1">8. Changes required <a class="header-anchor" href="#_8-changes-required" aria-label="Permalink to &quot;8. Changes required&quot;">​</a></h2><h3 id="cmake-modules-parse-cmake-sh" tabindex="-1"><code>cmake_modules/parse_cmake.sh</code> <a class="header-anchor" href="#cmake-modules-parse-cmake-sh" aria-label="Permalink to &quot;`cmake_modules/parse_cmake.sh`&quot;">​</a></h3><ul><li>Add <code>--no-push</code>. <code>doit</code> push commands record the refs instead of running.</li><li>Add a shared helm-publish function that publishes the hpcc, examples and managed charts.</li><li>New <code>cmake_modules/publish_helm.sh</code> republishes the charts for the current checkout.</li></ul><h3 id="cmake-modules-go-rc-sh" tabindex="-1"><code>cmake_modules/go_rc.sh</code> <a class="header-anchor" href="#cmake-modules-go-rc-sh" aria-label="Permalink to &quot;`cmake_modules/go_rc.sh`&quot;">​</a></h3><ul><li>Add <code>--gold</code>: release, sequence 1, the gold commit message, and gold helm publishing.</li><li>Without <code>--gold</code>, behaviour is unchanged.</li></ul><h3 id="cmake-modules-go-gold-sh" tabindex="-1"><code>cmake_modules/go_gold.sh</code> <a class="header-anchor" href="#cmake-modules-go-gold-sh" aria-label="Permalink to &quot;`cmake_modules/go_gold.sh`&quot;">​</a></h3><ul><li>Use the shared helm-publish function.</li></ul><h3 id="tools-tagging-gorc-sh" tabindex="-1"><code>tools/tagging/gorc.sh</code> <a class="header-anchor" href="#tools-tagging-gorc-sh" aria-label="Permalink to &quot;`tools/tagging/gorc.sh`&quot;">​</a></h3><ul><li>Pass <code>--gold</code> through.</li><li>Under <code>--gold</code>, use prepare-then-atomic-push for each repository.</li></ul><h3 id="new-tools-tagging-release-policy-branches-sh" tabindex="-1">New <code>tools/tagging/release-policy-branches.sh</code> <a class="header-anchor" href="#new-tools-tagging-release-policy-branches-sh" aria-label="Permalink to &quot;New `tools/tagging/release-policy-branches.sh`&quot;">​</a></h3><ul><li>Options: <code>--policy</code>, <code>--mode dry-run|apply</code>, <code>--branch auto|candidate-A.B.x</code>, <code>--force</code>.</li><li>Steps: <ol><li>Validate the policy.</li><li>Clone the tagged repositories and <code>helm-chart</code> side by side, without submodules.</li><li>Classify the state (section 6).</li><li>Detect changes (section 3).</li><li>Prepare (section 5).</li><li>Check the plan.</li><li>Push.</li></ol></li><li>App-token authentication through <code>GIT_CONFIG_*</code> environment variables, which child git commands inherit. Set the bot identity with <code>user.name</code> and <code>user.email</code>.</li><li>Exit codes: <ul><li>0: nothing to do, or done.</li><li>1: a push failed. This should trigger the webhook.</li><li>2: internal error or inconsistent state.</li></ul></li><li><code>dry-run</code> runs everything except the push and reports the plan.</li></ul><h3 id="new-tests-tools-tagging-tests-test-release-policy-branches-sh" tabindex="-1">New tests: <code>tools/tagging/tests/test-release-policy-branches.sh</code> <a class="header-anchor" href="#new-tests-tools-tagging-tests-test-release-policy-branches-sh" aria-label="Permalink to &quot;New tests: `tools/tagging/tests/test-release-policy-branches.sh`&quot;">​</a></h3><p>Use local bare repositories. Cover:</p><ul><li>no change</li><li>an empty upmerge only</li><li>a real change</li><li>a change only in a non-trigger repository</li><li>a change in one trigger repository → all repositories released</li><li>forced release</li><li>missing branch → abort</li><li>version disagreement → abort</li><li>the push for the 2nd repository fails (simulated with a pre-receive hook): no later pushes, rerun resumes, and no change detection is needed</li><li><code>helm-chart</code> push failure → resumed on rerun</li><li>gap in the released prefix → abort</li><li>a PR merged to <code>.x</code> between prepare and push → atomic rejection</li></ul><h3 id="github-workflows-branch-operations-yml" tabindex="-1"><code>.github/workflows/branch-operations.yml</code> <a class="header-anchor" href="#github-workflows-branch-operations-yml" aria-label="Permalink to &quot;`.github/workflows/branch-operations.yml`&quot;">​</a></h3><ul><li>New inputs: <code>run_tag</code>, <code>tag_mode</code>, <code>tag_branch</code>, <code>tag_force</code>.</li><li>Tagging step after upmerge: install helm, mint a write token (contents and workflows), run the script.</li><li>Tagging only runs when the operation covers all repositories (<code>repository == all</code>).</li><li>Automatic tagging is skipped if upmerge failed. <code>tag_force</code> doesn&#39;t override this.</li><li>Sync is skipped if tagging failed.</li><li>Extend the <code>notify-failure</code> message with the tagging summary.</li></ul><h3 id="github-workflows-branch-maintenance-yml" tabindex="-1"><code>.github/workflows/branch-maintenance.yml</code> <a class="header-anchor" href="#github-workflows-branch-maintenance-yml" aria-label="Permalink to &quot;`.github/workflows/branch-maintenance.yml`&quot;">​</a></h3><ul><li>Nightly: upmerge → tag (<code>auto</code>, apply) → sync.</li></ul><h3 id="new-github-workflows-branch-release-yml" tabindex="-1">New <code>.github/workflows/branch-release.yml</code> <a class="header-anchor" href="#new-github-workflows-branch-release-yml" aria-label="Permalink to &quot;New `.github/workflows/branch-release.yml`&quot;">​</a></h3><ul><li>Dispatch only. Inputs: <ul><li><code>branch</code> (choice: <code>auto</code> or one of the <code>.x</code> branches)</li><li><code>mode</code></li><li><code>force</code>: release even if nothing changed. It is still subject to the state and consistency checks.</li><li><code>upmerge</code> and <code>sync</code>: whether to run those steps around the tagging (both default to on).</li></ul></li><li>Runs upmerge → tag → sync through the reusable workflow.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li><code>tools/tagging/README.md</code>: describe the automatic path, the manual dispatch, recovery, and &quot;pause before manual tagging&quot;.</li></ul><h3 id="repository-settings" tabindex="-1">Repository settings <a class="header-anchor" href="#repository-settings" aria-label="Permalink to &quot;Repository settings&quot;">​</a></h3><ul><li>The App needs a ruleset bypass to create <code>candidate-*</code> branches and tags in all four tagged repositories.</li></ul>',71)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
